rule.definition:
if(
  a!isNullOrEmpty(ri!recordTypeUuid),
  #"SYSTEM_SYSRULES_httpResponse_v1"(
    statusCode: 400,
    headers: {
      #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
    },
    body: #"SYSTEM_SYSRULES_toJson_v1"(
      a!map(
        success: false,
        error: "MISSING_PARAMETER",
        message: "recordType UUID is required"
      )
    )
  ),
  a!localVariables(
    local!recordTypeRef: eval(concat("recordType!{", ri!recordTypeUuid, "}")),
    local!properties: a!recordTypeProperties(recordType: local!recordTypeRef),
    if(
      a!isNullOrEmpty(local!properties.recordType.fields),
      #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 404,
        headers: {
          #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
        },
        body: #"SYSTEM_SYSRULES_toJson_v1"(
          a!map(
            success: false,
            error: "RECORD_TYPE_NOT_FOUND",
            message: "No record type found for UUID: " & ri!recordTypeUuid
          )
        )
      ),
      a!localVariables(
        local!fields: #"SYSTEM_SYSRULES_forEach"(
          items: local!properties.recordType.fields,
          expression: a!map(
            name: fv!item.name,
            reference: tostring(fv!item.reference),
            displayName: fv!item.displayName,
            description: fv!item.description,
            type: fv!item.type,
            isPrimaryKey: fv!item.isPrimaryKey,
            isCustomRecordField: fv!item.isCustomRecordField,
            isSmartSearchEnabled: fv!item.isSmartSearchEnabled
          )
        ),
        #"SYSTEM_SYSRULES_httpResponse_v1"(
          statusCode: 200,
          headers: {
            #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
          },
          body: #"SYSTEM_SYSRULES_toJson_v1"(
            a!map(
              success: true,
              recordType: a!map(
                name: local!properties.recordType.name,
                fields: local!fields
              )
            )
          )
        )
      )
    )
  )
)
